class NotificationServer:
    """Manage clients and route notification messages through a transport."""

    def __init__(
        self,
        host: str = "127.0.0.1",
        port: int = 8765,
        redis_url: str | None = None,
        database_url: str | None = None,
        transport: BaseTransport | None = None,
        rate_limit: int | None = None,
        message_ttl_days: float | None = None,
    ) -> None:
        self.host = host
        self.port = port
        transport_name = os.getenv("TRANSPORT", "websocket").lower()
        if transport is None:
            if transport_name != "websocket":
                raise ValueError(f"unsupported transport: {transport_name}")
            transport = WebSocketTransport()
        self.transport = transport
        self.clients = transport.clients
        self.channels: dict[str, set[str]] = {}
        self._client_channels: dict[str, set[str]] = {}
        self._server: Any = None
        self.redis_url = redis_url if redis_url is not None else os.getenv("REDIS_URL")
        self.database_url = database_url or os.getenv("DATABASE_URL", "messages.db")
        self.rate_limit = rate_limit if rate_limit is not None else self._env_number("RATE_LIMIT", 100, int)
        self.message_ttl_days = (
            message_ttl_days
            if message_ttl_days is not None
            else self._env_number("MESSAGE_TTL_DAYS", 7, float)
        )
        self._redis: redis.Redis | None = None
        self._pubsub: redis.client.PubSub | None = None
        self._redis_task: asyncio.Task[None] | None = None
        self._cleanup_task: asyncio.Task[None] | None = None
        self._local_rate_limits: dict[str, deque[float]] = {}
        self._server_id = str(uuid.uuid4())
        self._database = self._sqlite_path(self.database_url)
        self._init_database()

    @staticmethod
    def _env_number(name: str, default: int | float, converter: Callable[[str], Any]) -> int | float:
        try:
            value = converter(os.getenv(name, str(default)))
            return value if value >= 0 else default
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _sqlite_path(database_url: str) -> str:
        if database_url.startswith("sqlite:///"):
            return database_url[9:]
        if database_url.startswith("sqlite://"):
            return database_url[9:]
        return database_url

    def _init_database(self) -> None:
        with sqlite3.connect(self._database) as connection:
            connection.execute(
                """CREATE TABLE IF NOT EXISTS messages (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    channel TEXT,
                    type TEXT NOT NULL,
                    payload TEXT NOT NULL,
                    timestamp TEXT NOT NULL
                )"""
            )

    async def _save_message(self, message: dict[str, Any]) -> None:
        await asyncio.to_thread(self._save_message_sync, message)

    def _save_message_sync(self, message: dict[str, Any]) -> None:
        with sqlite3.connect(self._database) as connection:
            connection.execute(
                "INSERT INTO messages (channel, type, payload, timestamp) VALUES (?, ?, ?, ?)",
                (
                    message.get("channel"),
                    message["type"],
                    json.dumps(message["payload"]),
                    message["timestamp"],
                ),
            )

    async def _get_messages(self, limit: int, offset: int) -> list[dict[str, Any]]:
        return await asyncio.to_thread(self._get_messages_sync, limit, offset)

    def _get_messages_sync(self, limit: int, offset: int) -> list[dict[str, Any]]:
        with sqlite3.connect(self._database) as connection:
            connection.row_factory = sqlite3.Row
            rows = connection.execute(
                "SELECT id, channel, type, payload, timestamp FROM messages "
                "ORDER BY id LIMIT ? OFFSET ?",
                (limit, offset),
            ).fetchall()
        return [
            {
                "id": row["id"],
                "channel": row["channel"],
                "type": row["type"],
                "payload": json.loads(row["payload"]),
                "timestamp": row["timestamp"],
            }
            for row in rows
        ]

